package com.autojobapply.tracking;
import com.autojobapply.model.*; import java.io.*; import java.nio.file.*; import java.sql.*; import java.time.*;
public final class ApplicationTracker implements AutoCloseable { private final Connection conn; public ApplicationTracker(Path db)throws SQLException{conn=DriverManager.getConnection("jdbc:sqlite:"+db.toAbsolutePath());}
 public void saveEmployer(String token,String company,String boardUrl,String apiUrl,String source,boolean valid){try(PreparedStatement p=conn.prepareStatement("INSERT INTO greenhouse_employers(board_token,company,board_url,api_url,source,validated,discovered_at,validated_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(board_token) DO UPDATE SET company=excluded.company,validated=excluded.validated,validated_at=excluded.validated_at")){String now=Instant.now().toString();p.setString(1,token);p.setString(2,company);p.setString(3,boardUrl);p.setString(4,apiUrl);p.setString(5,source);p.setInt(6,valid?1:0);p.setString(7,now);p.setString(8,valid?now:null);p.executeUpdate();}catch(SQLException e){throw new IllegalStateException(e);}}
 public void enqueue(ScoredJob job){try(PreparedStatement p=conn.prepareStatement("INSERT INTO application_queue(identity,priority,state,queued_at,updated_at,board_token,greenhouse_job_id,application_url) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT DO NOTHING")){String now=Instant.now().toString();String token=job.job().source().equals("Greenhouse")?job.job().company().toLowerCase().replaceAll("\\s+", "-"):null;p.setString(1,job.job().identity());p.setInt(2,job.score());p.setString(3,"READY_TO_APPLY");p.setString(4,now);p.setString(5,now);p.setString(6,token);p.setString(7,job.job().jobId());p.setString(8,job.job().applicationUrl());p.executeUpdate();}catch(SQLException e){throw new IllegalStateException(e);}}
 public void initialize()throws SQLException{try(Statement s=conn.createStatement()){s.executeUpdate("CREATE TABLE IF NOT EXISTS applications (identity TEXT PRIMARY KEY, company TEXT NOT NULL, title TEXT NOT NULL, location TEXT, job_id TEXT, score INTEGER, matching TEXT, missing TEXT, source TEXT, listing_url TEXT, application_url TEXT, discovered_at TEXT, attempted_at TEXT, submitted_at TEXT, status TEXT NOT NULL, confirmation TEXT, reason TEXT)");s.executeUpdate("CREATE TABLE IF NOT EXISTS greenhouse_employers (board_token TEXT PRIMARY KEY, company TEXT, board_url TEXT, api_url TEXT, source TEXT, validated INTEGER NOT NULL, discovered_at TEXT NOT NULL, validated_at TEXT)");s.executeUpdate("CREATE TABLE IF NOT EXISTS application_queue (identity TEXT PRIMARY KEY, priority INTEGER NOT NULL, state TEXT NOT NULL, queued_at TEXT NOT NULL, updated_at TEXT NOT NULL, board_token TEXT, greenhouse_job_id TEXT, application_url TEXT)");if(!queueColumn("board_token"))s.executeUpdate("ALTER TABLE application_queue ADD COLUMN board_token TEXT");if(!queueColumn("greenhouse_job_id"))s.executeUpdate("ALTER TABLE application_queue ADD COLUMN greenhouse_job_id TEXT");if(!queueColumn("application_url"))s.executeUpdate("ALTER TABLE application_queue ADD COLUMN application_url TEXT");s.executeUpdate("CREATE UNIQUE INDEX IF NOT EXISTS uq_queue_greenhouse ON application_queue(board_token,greenhouse_job_id) WHERE board_token IS NOT NULL AND greenhouse_job_id IS NOT NULL");}}
 private boolean queueColumn(String name)throws SQLException{try(Statement s=conn.createStatement();ResultSet r=s.executeQuery("PRAGMA table_info(application_queue)")){while(r.next())if(name.equalsIgnoreCase(r.getString("name")))return true;return false;}}
 public void saveGreenhouseJob(String token, Job j){if(token==null||token.isBlank()||j.jobId()==null||j.jobId().isBlank())throw new IllegalArgumentException("board token and job id required");try(Statement s=conn.createStatement()){s.executeUpdate("CREATE TABLE IF NOT EXISTS greenhouse_jobs (board_token TEXT NOT NULL, job_id TEXT NOT NULL, company TEXT, title TEXT, application_url TEXT, location TEXT, description TEXT, discovered_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, PRIMARY KEY(board_token,job_id))");}catch(SQLException e){throw new IllegalStateException(e);}try(PreparedStatement p=conn.prepareStatement("INSERT INTO greenhouse_jobs(board_token,job_id,company,title,application_url,location,description,discovered_at,last_seen_at) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(board_token,job_id) DO UPDATE SET company=COALESCE(NULLIF(excluded.company,''),greenhouse_jobs.company),title=COALESCE(NULLIF(excluded.title,''),greenhouse_jobs.title),application_url=COALESCE(NULLIF(excluded.application_url,''),greenhouse_jobs.application_url),location=COALESCE(NULLIF(excluded.location,''),greenhouse_jobs.location),description=COALESCE(NULLIF(excluded.description,''),greenhouse_jobs.description),last_seen_at=excluded.last_seen_at")){String now=Instant.now().toString();p.setString(1,token);p.setString(2,j.jobId());p.setString(3,j.company());p.setString(4,j.title());p.setString(5,j.applicationUrl());p.setString(6,j.location());p.setString(7,j.description());p.setString(8,now);p.setString(9,now);p.executeUpdate();}catch(SQLException e){throw new IllegalStateException(e);}}
 public int greenhouseJobCount()throws SQLException{try(Statement s=conn.createStatement();ResultSet r=s.executeQuery("SELECT count(*) FROM greenhouse_jobs")){return r.getInt(1);}}
 public boolean isKnown(Job j)throws SQLException{try(PreparedStatement p=conn.prepareStatement("SELECT 1 FROM applications WHERE identity=? AND status IN ('SUBMITTED','APPLYING','MATCHED','UNSUPPORTED','BLOCKED')")){p.setString(1,j.identity());return p.executeQuery().next();}}
 public void record(ScoredJob sj,ApplicationStatus status,String reason){Job j=sj.job();String sql="INSERT INTO applications(identity,company,title,location,job_id,score,matching,missing,source,listing_url,application_url,discovered_at,attempted_at,submitted_at,status,reason) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(identity) DO UPDATE SET score=excluded.score, matching=excluded.matching, missing=excluded.missing, attempted_at=excluded.attempted_at, status=excluded.status, reason=excluded.reason";try(PreparedStatement p=conn.prepareStatement(sql)){String now=Instant.now().toString();p.setString(1,j.identity());p.setString(2,j.company());p.setString(3,j.title());p.setString(4,j.location());p.setString(5,j.jobId());p.setInt(6,sj.score());p.setString(7,String.join(";",sj.matchingSkills()));p.setString(8,String.join(";",sj.missingSkills()));p.setString(9,j.source());p.setString(10,j.listingUrl());p.setString(11,j.applicationUrl());p.setString(12,now);p.setString(13,status==ApplicationStatus.MATCHED||status==ApplicationStatus.SKIPPED?null:now);p.setString(14,status==ApplicationStatus.SUBMITTED?now:null);p.setString(15,status.name());p.setString(16,reason);p.executeUpdate();}catch(SQLException e){throw new IllegalStateException("Could not save application record",e);}}
 public void exportCsv(Path csv)throws SQLException,IOException{Path parent=csv.getParent();if(parent!=null)Files.createDirectories(parent);try(BufferedWriter out=Files.newBufferedWriter(csv);Statement s=conn.createStatement();ResultSet r=s.executeQuery("SELECT company,title,location,job_id,score,matching,missing,source,listing_url,application_url,discovered_at,attempted_at,submitted_at,status,confirmation,reason FROM applications ORDER BY score DESC")){out.write("company,title,location,job_id,match_score,matching_qualifications,missing_qualifications,discovery_source,original_job_url,application_url,date_discovered,date_attempted,date_submitted,status,confirmation,reason\n");while(r.next()){for(int i=1;i<=16;i++){if(i>1)out.write(',');out.write(csv(r.getString(i)));}out.write('\n');}}}
 private String csv(String v){return "\""+(v==null?"":v.replace("\"","\"\""))+"\"";} public void close()throws SQLException{conn.close();}}
